:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font: 16px/1.5 system-ui, sans-serif;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 #0f0f1a;
  padding: 24px;
  width: 100%;
  max-width: 480px;
}
h1 {
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--accent);
}
.stats {
  display: flex;
  gap: 24px;
  margin-bottom: 20px;
  font-size: 1rem;
  color: var(--muted);
}
.stats span { color: var(--text); font-weight: bold; }
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  background: var(--bg);
  border: 2px solid var(--muted);
  border-radius: 0;
  color: var(--text);
  font: inherit;
  outline: none;
}
input[type="text"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}
button {
  padding: 10px 20px;
  background: var(--accent);
  color: #fff;
  border: 2px solid var(--accent);
  border-radius: 0;
  font: inherit;
  font-weight: bold;
  cursor: pointer;
  transition: transform 0.05s, background 0.1s;
}
button:hover { background: #ff5a7a; }
button:active { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
ul { list-style: none; }
li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 2px solid #0f0f1a;
}
li:last-child { border-bottom: none; }
li input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
li span {
  flex: 1;
  word-break: break-word;
}
li span.done {
  text-decoration: line-through;
  color: var(--muted);
}
li button {
  padding: 6px 12px;
  font-size: 0.875rem;
  background: transparent;
  border-color: var(--muted);
  color: var(--muted);
}
li button:hover { background: var(--accent); border-color: var(--accent); color: #fff; }
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

let nextId = 1;
const tasks = [];
const list = document.getElementById('todo-list');
const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + task.id;
  checkbox.checked = task.done;
  checkbox.setAttribute('aria-label', 'Mark task ' + task.id + ' complete');
  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    span.classList.toggle('done', task.done);
    updateCounts();
  });

  const label = document.createElement('label');
  label.htmlFor = checkbox.id;
  label.className = 'visually-hidden';
  label.textContent = 'Toggle task ' + task.id;

  const span = document.createElement('span');
  span.id = 'todo-text-' + task.id;
  span.textContent = task.text;
  if (task.done) span.classList.add('done');

  const delBtn = document.createElement('button');
  delBtn.id = 'todo-delete-' + task.id;
  delBtn.textContent = 'Delete';
  delBtn.setAttribute('aria-label', 'Delete task ' + task.id);
  delBtn.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx !== -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, label, span, delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', e => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
